(7095218, 1080592, 30982, '<td valign="top">I used to have some geraniums outside my back window I''d shoot through the glass.  I like the screen approach just as well if not better.  Lovely composition, nice light!</td>', 'I used to have some geraniums outside my back window I''d shoot through the glass.  I like the screen approach just as well if not better.  Lovely composition, nice light!', '2013-08-30 01:39:22.000000', NULL, 1),
(7095222, 1081271, 30982, '<td valign="top">You know, this is such a lovely photograph, and I am so pleased it is a minimal editing challenge.  People would be so tempted to edit the crap out of this and really, it''s just so very lovely as it is.  Very real.  Very warm.</td>', 'You know, this is such a lovely photograph, and I am so pleased it is a minimal editing challenge.  People would be so tempted to edit the crap out of this and really, it''s just so very lovely as it is.  Very real.  Very warm.', '2013-08-30 01:44:09.000000', NULL, 1),
