(7098577, 1081271, 12611, '<td valign="top">having a little girl roughly the same age, I understand the poignancy, the proportion, and perhaps photography''s noblest goal, to capture a scene, out of time, forever in the moment.</td>', 'having a little girl roughly the same age, I understand the poignancy, the proportion, and perhaps photography''s noblest goal, to capture a scene, out of time, forever in the moment.', '2013-09-05 09:47:54.000000', NULL, 1),
(7098579, 1080617, 12611, '<td valign="top">For me, the title, the "placement" of the objects within the composition, as well as the glorious sunrise all speak mysterious volumes about the day to come, the world as a perfect notion of human creation, existing because it has been thought about, given purpose.</td>', 'For me, the title, the "placement" of the objects within the composition, as well as the glorious sunrise all speak mysterious volumes about the day to come, the world as a perfect notion of human creation, existing because it has been thought about, given purpose.', '2013-09-05 09:50:51.000000', NULL, 1),
